import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxSelect,
  JxButton,
  JxDivider,
  JxBadge,
} from '@jinx-ui/react';

interface RegistrationData {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  address: string;
  comment: string;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'pl', label: 'Польша' },
  { value: 'de', label: 'Германия' },
  { value: 'kz', label: 'Казахстан' },
];

const emptyData: RegistrationData = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  address: '',
  comment: '',
};

export default function RegistrationWizard({ onSubmit }: { onSubmit: (data: RegistrationData) => void }) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(emptyData);

  const set = <K extends keyof RegistrationData>(key: K, value: RegistrationData[K]) =>
    setData((prev) => ({ ...prev, [key]: value }));

  const emailError = data.email.length > 0 && !data.email.includes('@') ? 'Укажите адрес с символом @' : undefined;

  const contactsValid = data.name.trim().length > 0 && data.email.includes('@');
  const addressValid = data.country.length > 0 && data.city.trim().length > 0 && data.address.trim().length > 0;
  const canGoNext = step === 0 ? contactsValid : step === 1 ? addressValid : true;

  const countryLabel = countries.find((country) => country.value === data.country)?.label ?? '—';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '24px', fontFamily: 'var(--jx-font-sans)' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={data.name}
            onChange={(event) => set('name', event.target.value)}
            placeholder="Иван Петров"
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={data.email}
            onChange={(event) => set('email', event.target.value)}
            errorText={emailError}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={data.phone}
            onChange={(event) => set('phone', event.target.value)}
            helperText="Необязательно"
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={data.country}
            onValueChange={(value) => set('country', value)}
          />
          <JxInputField
            label="Город"
            required
            value={data.city}
            onChange={(event) => set('city', event.target.value)}
          />
          <JxInputField
            label="Адрес"
            required
            value={data.address}
            onChange={(event) => set('address', event.target.value)}
            helperText="Улица, дом, квартира"
          />
          <JxTextareaField
            label="Комментарий к доставке"
            rows={3}
            maxLength={300}
            value={data.comment}
            onChange={(event) => set('comment', event.target.value)}
            helperText={`${data.comment.length}/300`}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxDivider label="Контакты" />
          <dl style={{ display: 'grid', gridTemplateColumns: 'auto 1fr', gap: '8px 16px', margin: 0 }}>
            <dt style={{ color: 'var(--jx-text-3)' }}>Имя</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{data.name}</dd>
            <dt style={{ color: 'var(--jx-text-3)' }}>Почта</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{data.email}</dd>
            <dt style={{ color: 'var(--jx-text-3)' }}>Телефон</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{data.phone ? `+7${data.phone}` : '—'}</dd>
          </dl>

          <JxDivider label="Адрес" />
          <dl style={{ display: 'grid', gridTemplateColumns: 'auto 1fr', gap: '8px 16px', margin: 0 }}>
            <dt style={{ color: 'var(--jx-text-3)' }}>Страна</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{countryLabel}</dd>
            <dt style={{ color: 'var(--jx-text-3)' }}>Город</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{data.city}</dd>
            <dt style={{ color: 'var(--jx-text-3)' }}>Адрес</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{data.address}</dd>
            <dt style={{ color: 'var(--jx-text-3)' }}>Комментарий</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>
              {data.comment || <JxBadge>пусто</JxBadge>}
            </dd>
          </dl>
        </div>
      )}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={() => setStep(step - 1)}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" disabled={!canGoNext} onClick={() => setStep(step + 1)}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={() => onSubmit(data)}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

